-- Clean up noisy/transient audit records accidentally generated by in-app notification reading, AI chats, and generic fallbacks
DELETE FROM audit_logs
WHERE action = 'Update System'
   OR entity_name = 'System'
   OR request_path LIKE '/api/notifications%'
   OR request_path LIKE '/api/v1/ai/conversations%'
   OR request_path = '/api/owner/admissions/ocr-scan'
   OR request_path = '/api/group-plans/preview';

